<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus,Copy}from'lucide-vue-next';const rows=ref<any[]>([]),open=ref(false),error=ref(''),created=ref<any|null>(null);const form=reactive({name:'Integração ERP',scopes:['documents:read','documents:retrieve'],entity_scope:[]});const cols=[{key:'name',label:'Aplicação'},{key:'client_id',label:'Client ID'},{key:'scopes',label:'Escopos'},{key:'active',label:'Situação'}];async function load(){rows.value=(await api.get('/api-clients')).data}async function save(){try{created.value=(await api.post('/api-clients',form)).data;open.value=false;await load()}catch(e){error.value=errorMessage(e)}}function copy(v:string){navigator.clipboard.writeText(v)}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))</script><template><PageHeader title="API e credenciais" subtitle="Crie integrações OAuth2 com escopos e limites por cliente/CNPJ"><button class="btn primary" @click="open=true"><Plus :size="16"/>Novo cliente de API</button></PageHeader><div v-if="created" class="secret-box"><strong>Credencial criada — copie o segredo agora</strong><div><code>{{created.client_id}}</code><button class="icon-button" @click="copy(created.client_id)"><Copy :size="16"/></button></div><div><code>{{created.client_secret}}</code><button class="icon-button" @click="copy(created.client_secret)"><Copy :size="16"/></button></div></div><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-scopes="{value}"><div class="tag-list"><span v-for="s in value">{{s}}</span></div></template><template #cell-active="{value}"><StatusBadge :status="value?'active':'disabled'"/></template></DataTable></section><Modal :open="open" title="Novo cliente de API" @close="open=false"><form class="form-grid" @submit.prevent="save"><label class="span-2">Nome<input v-model="form.name" required/></label><label class="span-2">Escopos<input value="documents:read, documents:retrieve" disabled/></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Gerar credencial</button></div></form></Modal></template>
